```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::response_channel;

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // The precondition guarantees len(text) <= 100000. Check it anyway so
        // that a contract breach upstream cannot reach the channel unnoticed.
        if reply.text.len() > 100_000 {
            panic!("SendReply: response text exceeds 100000 bytes");
        }

        // Send through the one granted capability. The host stamps the
        // session identity on the confirmation. The guest never makes it up.
        let confirmation = response_channel::send(&reply.text);

        // Postconditions: the reply was delivered and a session is present.
        // If the channel did not confirm delivery, trap. Returning a forged
        // `delivered: true` would be a lie, and returning `false` would
        // violate the contract.
        if !confirmation.delivered {
            panic!("SendReply: response channel did not confirm delivery");
        }
        if confirmation.session.is_empty() {
            panic!("SendReply: response channel returned no session identity");
        }

        confirmation
    }
}

export!(Node);
